-- ---------------------------------------------------------------------------
--  whip-racing -- 50 tracks.
--
--  Standalone. It creates the table if it is missing and then fills it, so it
--  runs against a fresh database or an established one without anything else
--  having been run first.
--
--  Taken from a racing_tracks dump with one change: the table name. Every
--  coordinate is byte-for-byte the original, which matters because a single
--  altered digit in a checkpoint stays invisible until somebody drives into a
--  wall.
--
--  It targets whip_racing_tracks rather than racing_tracks on purpose. racing_tracks
--  carries a foreign key from creatorStateId to racing_users(stateId), and the
--  creators here -- RT529JX7, VY6U0J6A, L0YN11M5 -- are not rows in that table,
--  so every insert is rejected with errno 1452. whip_racing_tracks has no such
--  constraint: a creator is resolved through recorded times instead.
--
--  Re-runnable: a track already present is refreshed rather than duplicated,
--  and an existing table is left alone rather than dropped, so nothing already
--  in it is lost.
--
--  Three tracks carry isDeleted = 1 -- Blackout (2), Industry Plant (4), and
--  test (48). They load, but stay hidden; the loader filters them out. 47 show.
--
--      mysql -u <user> -p <database> < tracks-data.sql
-- ---------------------------------------------------------------------------

-- Matches sql/install.sql. IF NOT EXISTS rather than DROP: on a server that
-- already has tracks, this file adds to them instead of replacing them.
CREATE TABLE IF NOT EXISTS `whip_racing_tracks` (
    `id` INT NOT NULL AUTO_INCREMENT,
    `name` VARCHAR(64) NOT NULL,
    `creatorStateId` VARCHAR(64) DEFAULT NULL,
    -- JSON array of { x, y, z, heading, radius }
    `checkpoints` LONGTEXT NOT NULL,
    -- JSON array of props placed along the route: { model, x, y, z, heading }
    `props` LONGTEXT DEFAULT NULL,
    `createdAt` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updatedAt` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `isPublished` TINYINT(1) NOT NULL DEFAULT 0,
    `isDeleted` TINYINT(1) NOT NULL DEFAULT 0,
    `isOfficial` TINYINT(1) NOT NULL DEFAULT 0,
    `isVerified` TINYINT(1) NOT NULL DEFAULT 0,
    `isFeatured` TINYINT(1) NOT NULL DEFAULT 0,
    -- 1 = point to point, 0 = circuit. Lap count is a per-race lobby setting.
    `isSprint` TINYINT(1) NOT NULL DEFAULT 1,
    PRIMARY KEY (`id`),
    KEY `creatorStateId` (`creatorStateId`),
    KEY `browse` (`isDeleted`, `isPublished`, `isFeatured`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

