ON DUPLICATE KEY UPDATE
    `name` = VALUES(`name`),
    `creatorStateId` = VALUES(`creatorStateId`),
    `checkpoints` = VALUES(`checkpoints`),
    `props` = VALUES(`props`),
    `createdAt` = VALUES(`createdAt`),
    `updatedAt` = VALUES(`updatedAt`),
    `isPublished` = VALUES(`isPublished`),
    `isDeleted` = VALUES(`isDeleted`),
    `isOfficial` = VALUES(`isOfficial`),
    `isVerified` = VALUES(`isVerified`),
    `isFeatured` = VALUES(`isFeatured`),
    `isSprint` = VALUES(`isSprint`);

SELECT
    COUNT(*)                                    AS imported,
    SUM(`isDeleted` = 0)                        AS visible,
    SUM(`isDeleted` = 1)                        AS hidden,
    SUM(`isDeleted` = 0 AND `isSprint` = 1)     AS sprints
FROM `whip_racing_tracks`;
